import{_ as a,o as t,c as n,ag as s}from"./chunks/framework.D9ghT4bC.js";const u=JSON.parse('{"title":"Unciv Lua API Extension (VSCode)","description":"","frontmatter":{},"headers":[],"relativePath":"Modders/Lua-API-Extension.md","filePath":"Modders/Lua-API-Extension.md"}'),o={name:"Modders/Lua-API-Extension.md"};function i(l,e,r,d,c,h){return t(),n("div",null,[...e[0]||(e[0]=[s(`<h1 id="unciv-lua-api-extension-vscode" tabindex="-1">Unciv Lua API Extension (VSCode) <a class="header-anchor" href="#unciv-lua-api-extension-vscode" aria-label="Permalink to &quot;Unciv Lua API Extension (VSCode)&quot;">​</a></h1><p><strong>One-time install, forever-fresh autocompletion.</strong> The <code>unciv-lua-api</code> VSCode extension is a thin cloud puller: every time you start VSCode (or open a <code>.lua</code> file) it fetches the latest <code>lua-api.lua</code> / <code>lua-map-api.lua</code> from the UncivCN docs site and syncs them into <code>~/.unciv/lua-api/</code>. Combined with the LuaLS language server you get autocompletion, hover docs and typo checking for <code>ctx.…</code> that <strong>never goes stale</strong> — no manual downloads, no copying files, no checking for updates.</p><h2 id="why-you-want-this" tabindex="-1">Why you want this <a class="header-anchor" href="#why-you-want-this" aria-label="Permalink to &quot;Why you want this&quot;">​</a></h2><p>The Lua API definitions (<code>lua-api.lua</code> / <code>lua-map-api.lua</code>, generated from the game code) change with every game release. Copying them into your mod by hand means:</p><ul><li>you forget to check for new releases → stale autocompletion, wrong hints;</li><li>every mod needs its own copy that must be re-synced;</li><li>new APIs (e.g. <code>civ.discoverTech()</code>) simply don&#39;t autocomplete until you remember to update.</li></ul><p>The extension solves this by separating <strong>data from logic</strong>: the definitions live in the cloud (deployed automatically on every release) and the extension just pulls them. The extension itself almost never needs updating.</p><h2 id="install" tabindex="-1">Install <a class="header-anchor" href="#install" aria-label="Permalink to &quot;Install&quot;">​</a></h2><ol><li><strong>Install the Lua language server</strong>: in VSCode, install the <strong>Lua</strong> extension by sumneko (the LuaLS language server).</li><li><strong>Install the Unciv Lua API extension</strong>: download <code>unciv-lua-api.vsix</code> from the latest <a href="https://github.com/AutumnPizazz/Unciv/releases" target="_blank" rel="noreferrer">UncivCN release</a> (it&#39;s attached to every release, ~6 KB), then in VSCode run <strong>Extensions → ⋯ → Install from VSIX…</strong> and pick the file.</li><li><strong>Configure once</strong>: open the command palette (Ctrl+Shift+P) and run <strong>Unciv: Configure Lua API autocompletion</strong>. It adds <code>~/.unciv/lua-api</code> (absolute path) to your user-level <code>Lua.workspace.library</code> setting — this applies to <strong>every mod workspace</strong> on your machine, you never do this again.</li></ol><p>Done. Open any mod folder and start writing: <code>ctx.</code> autocompletes, hovering <code>ctx.civ.addGold(</code> shows its signature, typos like <code>ctx.civ.addGoldd(...)</code> get red squiggles immediately. Map scripts (<code>GenerateMap(ctx)</code>) get the same treatment from <code>lua-map-api.lua</code> — both files are managed automatically.</p><h2 id="how-it-works" tabindex="-1">How it works <a class="header-anchor" href="#how-it-works" aria-label="Permalink to &quot;How it works&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Game code → generates lua-api.lua / lua-map-api.lua (with a -- Unciv version: header)</span></span>
<span class="line"><span>    ↓ deployed automatically on every release</span></span>
<span class="line"><span>docs site: https://club.unciv.cn/Unciv/Modders/lua-api.lua</span></span>
<span class="line"><span>    ↓ pulled on every VSCode start / on opening a .lua file (fallback: GitHub raw)</span></span>
<span class="line"><span>extension → ~/.unciv/lua-api/</span></span>
<span class="line"><span>    ↓ one-click configure</span></span>
<span class="line"><span>LuaLS workspace.library (user-level setting) → autocompletion everywhere</span></span></code></pre></div><ul><li><strong>Update check</strong>: the generated files carry a <code>-- Unciv version: 4.21.6.6 (build 1250)</code> header, so old and new copies are instantly distinguishable; the extension only writes when the content actually changed.</li><li><strong>Offline</strong>: if the cloud is unreachable, the last synced copy is kept (with its version header) and your autocompletion keeps working; it catches up automatically next time.</li><li><strong>Manual refresh</strong>: command palette → <strong>Unciv: Update Lua API definitions now</strong>.</li></ul><h2 id="manual-setup-alternative" tabindex="-1">Manual setup (alternative) <a class="header-anchor" href="#manual-setup-alternative" aria-label="Permalink to &quot;Manual setup (alternative)&quot;">​</a></h2><p>If you prefer not to use the extension, copy the definitions from the repo&#39;s <code>docs/Modders/</code> (or from <a href="https://club.unciv.cn/Unciv/Modders/lua-api.lua" target="_blank" rel="noreferrer">the docs site</a>) into your mod and create a <code>.luarc.json</code>:</p><div class="language-json vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">json</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">{</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">    &quot;runtime.version&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;Lua 5.2&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">    &quot;workspace.library&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: [</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">        &quot;.lua-api&quot;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    ],</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">    &quot;diagnostics.globals&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: [</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;ctx&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}</span></span></code></pre></div><p>Remember to re-copy the files after each game update — this is exactly the chore the extension eliminates.</p><h2 id="faq" tabindex="-1">FAQ <a class="header-anchor" href="#faq" aria-label="Permalink to &quot;FAQ&quot;">​</a></h2><p><strong>Does this require the game or the source code?</strong> No. Only VSCode + the Lua language server + this extension.</p><p><strong>Why isn&#39;t it on the VSCode marketplace?</strong> The extension is deliberately a thin puller — the definitions come from the cloud in real time, so it doesn&#39;t depend on marketplace auto-updates to stay fresh. If it ever needs a marketplace listing (Open VSX / VSCode Marketplace), publishing is a one-step CI addition; the extension itself doesn&#39;t change.</p><p><strong>I use VSCodium / Cursor / another LuaLS-capable editor?</strong> The extension targets VSCode&#39;s extension API; on other editors you can still get the same result by pointing LuaLS&#39;s <code>workspace.library</code> at <code>~/.unciv/lua-api</code> (after running the extension once in VSCode, or syncing the files by hand).</p><p><strong>Where do the definitions come from?</strong> They are generated from the game code (<code>LuaApiDocs</code> / <code>LuaMapGenApiDocs</code> tables, see <a href="./../UncivCN/Coding-standards.html">Coding Standards</a>) — the same source as <a href="./Lua-API-Reference.html">Lua API Reference</a>, so the docs you read online and the definitions in your editor can never disagree.</p><h2 id="see-also" tabindex="-1">See also <a class="header-anchor" href="#see-also" aria-label="Permalink to &quot;See also&quot;">​</a></h2><ul><li><a href="./Lua-Modding.html">Lua Mod Scripts</a> — tutorials, triggers and lifecycle hooks</li><li><a href="./Lua-API-Reference.html">Lua API Reference</a> — every function and property of the context tables</li><li><a href="./Lua-Map-API-Reference.html">Lua Map-Script API Reference</a> — the generation-only API for map scripts</li></ul>`,23)])])}const g=a(o,[["render",i]]);export{u as __pageData,g as default};
